    const content=$('#detail-content'),quickNav=document.createElement('nav'),summaryRoot=document.createElement('div');quickNav.className='profile-quick-nav';quickNav.setAttribute('aria-label','Profilnavigation');quickNav.innerHTML='<button type="button" data-profile-section="personal-summary">Sammanfattning</button><button type="button" data-profile-section="detail-replay">Replay</button><button type="button" data-profile-section="profile-journey">Loppets utveckling</button><button type="button" data-profile-section="split-section">Mellantider</button>';content.querySelector('.detail-hero').after(quickNav);content.querySelector('.detail-facts').after(summaryRoot);content.querySelector('.insight-cards')?.remove();window.GPersonalSummary.render(summaryRoot,{summary:adapter.personalRaceSummary(record),selected:state.duelIds.includes(record.id),onCompare:()=>{toggleFavoriteComparison(record);window.GPersonalSummary.render(summaryRoot,{summary:adapter.personalRaceSummary(record),selected:state.duelIds.includes(record.id),onCompare:()=>toggleFavoriteComparison(record)})}});$$('[data-profile-section]',quickNav).forEach(button=>button.onclick=()=>{const target=button.dataset.profileSection==='split-section'?content.querySelector('.split-section'):document.getElementById(button.dataset.profileSection);target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});
