    $('#detail-placement').innerHTML=window.GCharts.lines([{name:'Totalplacering',values:profile.segments.map(segment=>segment.to.placeOverall),color:'#0b6671'},...(record.isRelay&&!relayMeta.ranked?[]:[{name:'Klassplacering',values:profile.segments.map(segment=>segment.to.placeClass),color:'#138a78'}]),...(!record.isRelay?[{name:'Könsplacering',values:profile.segments.map(segment=>segment.to.placeGender),color:window.GCharts.SEX_COLORS[record.sex]}]:[])],labels,{format:value=>`#${Math.round(value)}`});
