  function syncNavigation(){if($('#detail-dialog')?.open||$('#duel-dialog')?.open||$('#head-to-head-dialog')?.open||state.restoringSection)return;const sections=['runner-lookup','map-duel','overview','statistics','gender','age-analysis','segments','clubs','results'],offset=window.scrollY+150;let active='runner-lookup';for(const id of sections){const element=document.getElementById(id);if(element&&!element.hidden&&element.offsetTop<=offset)active=id}state.activeSection=active;$$('.analysis-nav [data-target]').forEach(button=>button.classList.toggle('active',button.dataset.target===active))}
  function syncUrlState(){const url=new URL(location.href),filters=currentFilters();url.search='';url.searchParams.set('race',state.raceKey);if(state.activeSection&&state.activeSection!=='overview')url.searchParams.set('section',state.activeSection);if(filters.sex)url.searchParams.set('sex',filters.sex);if(filters.className)url.searchParams.set('class',filters.className);if(filters.status)url.searchParams.set('status',filters.status);if(filters.club)url.searchParams.set('club',filters.club);if(state.unit!=='pace')url.searchParams.set('unit',state.unit);if(state.selectedRecordId)url.searchParams.set('runner',state.selectedRecordId.split(':').at(-1));if(state.duelIds.length)url.searchParams.set('duel',state.duelIds.map(id=>id.split(':').at(-1)).join(','));history.replaceState(null,'',url)}
  async function shareView(){syncNavigation();syncUrlState();try{await navigator.clipboard.writeText(location.href);$('#share-view').textContent='Länk kopierad';setTimeout(()=>$('#share-view').textContent='Dela',1800)}catch{prompt('Kopiera länken:',location.href)}}
